def f(x, y, z, w):
    return x**4 + y**4 + z**4 + w**4 - 8 * (x**3 + y**3 + z**3 + w**3)

# Check case {4, 4, 4, 0}
val1 = f(4, 4, 4, 0)
print(f"Value for (4, 4, 4, 0): {val1}")

# Check case {2, 2, 2, 6}
val2 = f(2, 2, 2, 6)
print(f"Value for (2, 2, 2, 6): {val2}")

# Check case {a, a, b, b} where {a, b} = {3+sqrt(3), 3-sqrt(3)}
import numpy as np
a = 3 + np.sqrt(3)
b = 3 - np.sqrt(3)
# F = 2(a^4+b^4) - 16(a^3+b^3) = -720
val3 = f(a, a, b, b)
print(f"Value for (a, a, b, b): {val3}")
